const specs = [
  {cmd:"script -q -e -c 'tail -12 /audit-output/REVIEW.md' /audit-output/evidence/134-review-tail.txt", max_output_tokens:5000},
  {cmd:"script -q -e -c 'rg -n \"^(VERDICT|LEGITIMACY):\" /audit-output/REVIEW.md' /audit-output/evidence/135-review-verdict-lines.txt", max_output_tokens:5000},
  {cmd:"script -q -e -c 'wc -l -w -c /audit-output/REVIEW.md' /audit-output/evidence/136-review-size.txt", max_output_tokens:3000},
  {cmd:"script -q -e -c 'test -s /audit-output/REVIEW.md' /audit-output/evidence/137-review-nonempty.txt", max_output_tokens:2000}
];
const rs = await Promise.all(specs.map(s => tools.exec_command({...s,workdir:"/audit-output",yield_time_ms:10000})));
rs.forEach((r,i)=>text(`--- ${i} exit=${r.exit_code}\n${r.output}`));
